// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h1, bytes32 h2) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        // First lock-in succeeds for any admissible input.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        // A second lock-in while a guess is pending must revert.
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(h2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
